sys_script_include.script:
var ExtractionApplier = Class.create();

// Entity types that ARE insurable objects (tables extending x_gegis_ins_policy_insurable_object).
ExtractionApplier.OBJECT_SUBTYPES = ['building', 'driver', 'class_exposure', 'scheduled_equipment', 'cyber_profile', 'underlying_policy'];
// Entity types whose records are anchored to an insurable_object identity row.
ExtractionApplier.ANCHORED = ['location', 'vehicle'];

ExtractionApplier.prototype = {
    initialize: function() {
        this.ENTITY = 'x_gegis_ins_policy_extraction_entity';
        this.FIELD = 'x_gegis_ins_policy_extraction_field';
        this.APPLIABLE = 'accepted,auto_accepted,corrected';
    },

    /**
     * Apply one reviewed extraction to the system of record.
     * Accepted entities become (or update) target records; accepted and
     * corrected fields write their final value onto the target column.
     * Locations, vehicles and other insurable objects also get their
     * insurable_object identity and a submission_risk participation row.
     * Runs as the session user so sys_audit attributes changes correctly.
     *
     * @param extractionGr GlideRecord x_gegis_ins_policy_extraction
     * @return Number of field values applied
     */
    apply: function(extractionGr) {
        var extractionId = extractionGr.getUniqueValue();
        var submissionId = String(extractionGr.submission);
        var entityTarget = this._materializeEntities(extractionId, submissionId);

        var applied = 0;
        var f = new GlideRecord(this.FIELD);
        f.addQuery('extraction', extractionId);
        f.addQuery('review_status', 'IN', this.APPLIABLE);
        f.query();
        while (f.next()) {
            var targetId = f.entity ? entityTarget[String(f.entity)] : '';
            if (!targetId && String(f.target_table) === 'x_gegis_ins_policy_submission')
                targetId = submissionId;
            if (!targetId)
                continue;
            if (this._writeValue(f, targetId)) {
                f.target_sys_id = targetId;
                f.applied_by = gs.getUserID();
                f.applied_on = new GlideDateTime();
                f.review_status = 'applied';
                f.update();
                applied++;
            }
        }

        extractionGr.disposition = 'applied';
        extractionGr.extraction_status = 'reviewed';
        extractionGr.update();
        this._touchSubmission(submissionId, extractionId);
        return applied;
    },

    /**
     * The agreed truth for a field. First one present wins:
     *
     *   override_value  a privileged correction - outranks everything, and is
     *                   the only one that carries an override_reason
     *   manual_value    an ordinary human entry
     *   mapped_value    the normalised form produced by the mapping rule
     *                   (value map, date / number format), which is what should
     *                   reach the target column, not the raw text
     *   extracted_value the raw text as read off the document
     */
    getFinalValue: function(fieldGr) {
        var override = String(fieldGr.override_value);
        if (override)
            return override;
        var manual = String(fieldGr.manual_value);
        if (manual)
            return manual;
        var mapped = String(fieldGr.mapped_value);
        return mapped ? mapped : String(fieldGr.extracted_value);
    },

    /** Create target records for accepted entities; reuse matched ones. */
    _materializeEntities: function(extractionId, submissionId) {
        var map = {};
        var owner = this._owner(submissionId);
        var e = new GlideRecord(this.ENTITY);
        e.addQuery('extraction', extractionId);
        e.addQuery('disposition', 'IN', 'accepted,merged');
        e.query();
        while (e.next()) {
            var targetId = String(e.matched_record);
            var table = String(e.matched_table);
            var type = String(e.entity_type);
            if (!targetId) {
                table = 'x_gegis_ins_policy_' + type;
                var t = new GlideRecord(table);
                if (!t.isValid())
                    continue;
                t.initialize();
                if (t.isValidField('submission'))
                    t.submission = submissionId;
                var isObject = ExtractionApplier.OBJECT_SUBTYPES.indexOf(type) > -1;
                if (isObject) {
                    t.setValue('name', String(e.label) || type);
                    t.setValue('object_type', type);
                    t.setValue('status', Constants.CHOICE.OBJECT_STATUS.ACTIVE);
                    t.setValue('owner_party', owner);
                }
                targetId = t.insert();
                var objectId = isObject ? targetId : '';
                if (ExtractionApplier.ANCHORED.indexOf(type) > -1)
                    objectId = this._anchor(table, targetId, type, String(e.label), owner);
                if (objectId && submissionId)
                    this._participate(submissionId, objectId);
                e.matched_table = table;
                e.matched_record = targetId;
                e.match_status = 'matched';
                e.update();
            }
            map[e.getUniqueValue()] = targetId;
        }
        return map;
    },

    // One identity row per location / vehicle, so quote and policy risks reuse it.
    _anchor: function(table, recordId, type, label, owner) {
        var io = new GlideRecord(Constants.TABLE.INSURABLE_OBJECT);
        io.initialize();
        io.setValue('name', label || type);
        io.setValue('object_type', type);
        io.setValue('status', Constants.CHOICE.OBJECT_STATUS.ACTIVE);
        io.setValue('owner_party', owner);
        var ioId = io.insert();
        var rec = new GlideRecord(table);
        if (rec.get(recordId) && rec.isValidField('insurable_object')) {
            rec.setValue('insurable_object', ioId);
            rec.update();
        }
        return ioId;
    },

    _participate: function(submissionId, objectId) {
        var sr = new GlideRecord(Constants.TABLE.SUBMISSION_RISK);
        sr.addQuery('submission', submissionId);
        sr.addQuery('insurable_object', objectId);
        sr.setLimit(1);
        sr.query();
        if (sr.next())
            return sr.getUniqueValue();
        sr.initialize();
        sr.setValue('submission', submissionId);
        sr.setValue('insurable_object', objectId);
        sr.setValue('source', Constants.CHOICE.RECORD_SOURCE.EXTRACTED);
        return sr.insert();
    },

    _owner: function(submissionId) {
        var sub = new GlideRecord('x_gegis_ins_policy_submission');
        return submissionId && sub.get(submissionId) ? String(sub.getValue('primary_insured') || '') : '';
    },

    _writeValue: function(fieldGr, targetId) {
        var gr = new GlideRecord(String(fieldGr.target_table));
        if (!gr.isValid() || !gr.get(targetId))
            return false;
        var column = String(fieldGr.target_column);
        if (!gr.isValidField(column))
            return false;
        gr.setValue(column, this.getFinalValue(fieldGr));
        gr.update();
        return true;
    },

    _touchSubmission: function(submissionId, extractionId) {
        if (!submissionId)
            return;
        var sub = new GlideRecord('x_gegis_ins_policy_submission');
        if (sub.get(submissionId)) {
            sub.current_extraction = extractionId;
            sub.extraction_status = 'applied';
            sub.update();
        }
    },

    type: 'ExtractionApplier'
};
